add_action( 'product_cat_add_form_fields', 'perfectpixel_cat_bottom_desc_add_field' );
add_action( 'product_cat_edit_form_fields', 'perfectpixel_cat_bottom_desc_edit_field' );
add_action( 'created_product_cat', 'perfectpixel_cat_bottom_desc_save' );
add_action( 'edited_product_cat', 'perfectpixel_cat_bottom_desc_save' );
add_action( 'woocommerce_after_shop_loop', 'perfectpixel_cat_bottom_desc_output', 50 );

function perfectpixel_cat_bottom_desc_add_field() {
	echo '<div class="form-field"><label for="perfectpixel_bottom_desc">' . esc_html( '{{cat_bottom_desc_label}}' ) . '</label>';
	wp_nonce_field( 'perfectpixel_cat_bottom_desc', 'perfectpixel_cat_bottom_desc_nonce' );
	wp_editor( '', 'perfectpixel_bottom_desc', array( 'textarea_rows' => 6, 'media_buttons' => false ) );
	echo '</div>';
}

function perfectpixel_cat_bottom_desc_edit_field( $term ) {
	echo '<tr class="form-field"><th scope="row"><label for="perfectpixel_bottom_desc">' . esc_html( '{{cat_bottom_desc_label}}' ) . '</label></th><td>';
	wp_nonce_field( 'perfectpixel_cat_bottom_desc', 'perfectpixel_cat_bottom_desc_nonce' );
	wp_editor( get_term_meta( $term->term_id, 'perfectpixel_bottom_desc', true ), 'perfectpixel_bottom_desc', array( 'textarea_rows' => 8 ) );
	echo '</td></tr>';
}

function perfectpixel_cat_bottom_desc_save( $term_id ) {
	if ( ! isset( $_POST['perfectpixel_cat_bottom_desc_nonce'], $_POST['perfectpixel_bottom_desc'] ) || ! current_user_can( 'manage_product_terms' ) ) {
		return;
	}
	if ( ! wp_verify_nonce( sanitize_key( $_POST['perfectpixel_cat_bottom_desc_nonce'] ), 'perfectpixel_cat_bottom_desc' ) ) {
		return;
	}
	update_term_meta( $term_id, 'perfectpixel_bottom_desc', wp_kses_post( wp_unslash( $_POST['perfectpixel_bottom_desc'] ) ) );
}

function perfectpixel_cat_bottom_desc_output() {
	if ( ! is_product_category() || is_paged() ) {
		return;
	}
	$content = get_term_meta( get_queried_object_id(), 'perfectpixel_bottom_desc', true );
	if ( $content ) {
		echo '<div class="term-description perfectpixel-cat-bottom-desc" style="clear:both;margin-top:2em">' . wp_kses_post( wpautop( do_shortcode( $content ) ) ) . '</div>';
	}
}
